instruction:
Din documentul de mai jos, identifică valorile cerute de schema JSON. Menționează în limba română ce tip de document ai citit și ce câmpuri ai completat, iar la finalul răspunsului scrie obiectul JSON.

Schema:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "document_type",
    "series",
    "number",
    "holder_name",
    "issuing_authority",
    "loss_date",
    "city"
  ],
  "properties": {
    "document_type": {
      "type": "string",
      "enum": [
        "CI",
        "pașaport",
        "permis auto",
        "certificat de înmatriculare"
      ]
    },
    "series": {
      "type": "string",
      "pattern": "^[A-Z]{2}$"
    },
    "number": {
      "type": "string",
      "pattern": "^\\d{6}$"
    },
    "holder_name": {
      "type": "string"
    },
    "issuing_authority": {
      "type": "string"
    },
    "loss_date": {
      "type": "string",
      "pattern": "^\\d{4}-\\d{2}-\\d{2}$"
    },
    "city": {
      "type": "string"
    }
  }
}

